// #3f693e Regression test: משתמש רגיל не может редактировать экран «מידע להתאמת מכרזים» (/onboarding).
// Кейсы: .qa/tests/permissions-isolation/PI-13 (прямой заход/reload/SPA), PI-14 (390 px), PI-15 (ADMIN, контроль).
// Только просмотр: ничего не сохраняется и не нажимается, кроме «חזרה לדף הבית». Любая запись в company_profiles = падение.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { authState } from '../helpers/tenderflow';
import { ACCOUNT_ADMINS_ONLY } from './test-data';

const FORBIDDEN_TITLE = 'אין לך הרשאה למסך זה';
const BACK_HOME = 'חזרה לדף הבית';

// inv14 (משתמש רגיל компании B) — вне типа authState, путь строим сами. Пароли не используются.
const sessionOf = (id: 'user' | 'inv14') => (id === 'user' ? authState('user') : path.resolve(__dirname, '../../../auth/inv14.json'));

/** Все запросы записи (не GET/HEAD/OPTIONS) к company_profiles за время теста. */
function trackProfileWrites(page: Page): string[] {
  const writes: string[] = [];
  page.on('request', (r) => {
    if (/\/rest\/v1\/company_profiles/.test(r.url()) && !['GET', 'HEAD', 'OPTIONS'].includes(r.method())) {
      writes.push(`${r.method()} ${r.url()}`);
    }
  });
  return writes;
}

/** Заглушка: заголовок + пояснение + «חזרה לדף הבית», ни одного поля ввода и контролов мастера. */
async function expectForbiddenStub(page: Page) {
  await expect(page.getByText(FORBIDDEN_TITLE)).toBeVisible();
  await expect(page.getByText(ACCOUNT_ADMINS_ONLY, { exact: true })).toBeVisible();
  await expect(page.getByRole('link', { name: BACK_HOME }).or(page.getByRole('button', { name: BACK_HOME }))).toBeVisible();
  for (const role of ['textbox', 'combobox', 'spinbutton', 'checkbox', 'radio', 'switch', 'slider'] as const) {
    await expect(page.getByRole(role), `поля ввода (${role}) на заглушке быть не должно`).toHaveCount(0);
  }
  await expect(page.locator('input:not([type="hidden"]), textarea, select, [contenteditable="true"]')).toHaveCount(0);
  await expect(page.getByRole('tablist', { name: 'פרופיל החברה' })).toHaveCount(0);
  await expect(page.getByRole('heading', { name: /^שלב \d מתוך 4:/ })).toHaveCount(0);
}

for (const who of ['user', 'inv14'] as const) {
  test.describe(`/onboarding — משתמש רגיל (${who})`, () => {
    test.use({ storageState: sessionOf(who) });

    test(`כניסה ישירה ל-/onboarding: "אין לך הרשאה למסך זה", בלי שדות ובלי כתיבה ל-company_profiles (${who}) #3f693e @desktop @prod-safe`, async ({ page }) => {
      const writes = trackProfileWrites(page);
      await page.goto('/onboarding');
      await expectForbiddenStub(page);
      expect(writes, 'member не должен слать запись в company_profiles').toEqual([]);
    });

    test(`רענון הדף ב-/onboarding שומר על החסימה (${who}) #3f693e @desktop @prod-safe`, async ({ page }) => {
      const writes = trackProfileWrites(page);
      await page.goto('/onboarding');
      await expect(page.getByText(FORBIDDEN_TITLE)).toBeVisible();
      await page.reload();
      await expectForbiddenStub(page);
      expect(writes, 'member не должен слать запись в company_profiles').toEqual([]);
    });

    test(`מעבר פנימי (SPA) ל-/onboarding חסום כמו כניסה ישירה (${who}) #3f693e @desktop @prod-safe`, async ({ page }) => {
      const writes = trackProfileWrites(page);
      await page.goto('/');
      await expect(page.getByRole('navigation', { name: 'ניווט ראשי' })).toBeVisible();
      // Внутренний переход без перезагрузки: history API + popstate (react-router).
      await page.evaluate(() => {
        window.history.pushState({}, '', '/onboarding');
        window.dispatchEvent(new PopStateEvent('popstate'));
      });
      await expect(page).toHaveURL(/\/onboarding$/);
      await expectForbiddenStub(page);
      expect(writes, 'member не должен слать запись в company_profiles').toEqual([]);
    });

    test(`"חזרה לדף הבית" מוציא מהמסך החסום (${who}) #3f693e @desktop @prod-safe`, async ({ page }) => {
      await page.goto('/onboarding');
      await page.getByRole('link', { name: BACK_HOME }).or(page.getByRole('button', { name: BACK_HOME })).click();
      await expect(page).not.toHaveURL(/\/onboarding/);
      await expect(page.getByRole('navigation', { name: 'ניווט ראשי' })).toBeVisible();
    });
  });
}

test.describe('/onboarding ברוחב 390 — משתמש רגיל', () => {
  test.use({ storageState: sessionOf('user') });

  test('ב-390px: החסימה מוצגת בלי גלילה אופקית #3f693e @desktop @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('/onboarding');
    await expectForbiddenStub(page);
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    expect(overflow, 'горизонтального скролла быть не должно').toBeLessThanOrEqual(0);
  });
});

// Контроль: ADMIN тот же адрес открывает — проверки выше не пустые. Только чтение, ничего не сохраняется.
test.describe('/onboarding — מנהל חשבון (בקרה)', () => {
  test.use({ storageState: authState('admin') });

  test('מנהל חשבון רואה את לשוניות פרופיל החברה בלי חסימה #3f693e @desktop @prod-safe', async ({ page }) => {
    const writes = trackProfileWrites(page);
    await page.goto('/onboarding');
    await expect(page.getByRole('tablist', { name: 'פרופיל החברה' })).toBeVisible();
    await expect(page.getByRole('tabpanel')).toBeVisible();
    await expect(page.getByText(FORBIDDEN_TITLE)).toHaveCount(0);
    await expect(page.getByText(ACCOUNT_ADMINS_ONLY, { exact: true })).toHaveCount(0);
    expect(writes, 'просмотр не должен писать в company_profiles').toEqual([]);
  });
});
